663:     /**
664:      * Creates the parallelism store that should be used to build the {@link ExecutionGraph}, which
665:      * will respect the vertex parallelism of the passed {@link JobGraph} in all execution modes.
666:      *
667:      * @param jobGraph The job graph for execution.
668:      * @param executionMode The mode of scheduler execution.
669:      * @param defaultMaxParallelismFunc a function for computing a default max parallelism if none
670:      *     is specified on a given vertex
671:      * @return The parallelism store.
672:      */
673:     @VisibleForTesting
674:     static VertexParallelismStore computeVertexParallelismStoreForExecution(
675:             JobGraph jobGraph,
676:             SchedulerExecutionMode executionMode,
677:             Function<JobVertex, Integer> defaultMaxParallelismFunc) {
678:         if (executionMode == SchedulerExecutionMode.REACTIVE) {
679:             return computeReactiveModeVertexParallelismStore(
680:                     jobGraph.getVertices(), defaultMaxParallelismFunc, false);
681:         }
682:         return SchedulerBase.computeVertexParallelismStore(
683:                 jobGraph.getVertices(), defaultMaxParallelismFunc);
684:     }
