1424:                 initializationTimestamp,
1425:                 vertexAttemptNumberStore,
1426:                 adjustedParallelismStore,
1427:                 deploymentTimeMetrics,
1428:                 // adaptive scheduler works in streaming mode, actually it only
1429:                 // supports must be pipelined result partition, mark partition finish is
