704:     @Override
705:     public CompletableFuture<Void> closeAsync() {
706:         LOG.debug("Closing the AdaptiveScheduler. Trying to suspend the current job execution.");
707: 
708:         state.suspend(new FlinkException("AdaptiveScheduler is being stopped."));
709: 
710:         Preconditions.checkState(
711:                 state instanceof Finished,
712:                 "Scheduler state should be finished after calling state.suspend.");
713: 
714:         backgroundTask.abort();
715:         // wait for the background task to finish and then close services
716:         return FutureUtils.composeAfterwards(
717:                 FutureUtils.runAfterwardsAsync(
718:                         backgroundTask.getTerminationFuture(),
719:                         () -> stopCheckpointServicesSafely(jobTerminationFuture.get()),
720:                         getMainThreadExecutor()),
721:                 checkpointsCleaner::closeAsync);
722:     }
723: 
724:     private void stopCheckpointServicesSafely(JobStatus terminalState) {
725:         LOG.debug("Stopping the checkpoint services with state {}.", terminalState);
726: 
727:         Exception exception = null;
728: 
729:         try {
730:             completedCheckpointStore.shutdown(terminalState, checkpointsCleaner);
731:         } catch (Exception e) {
732:             exception = e;
733:         }
734: 
735:         try {
736:             checkpointIdCounter.shutdown(terminalState).get();
737:         } catch (Exception e) {
738:             exception = ExceptionUtils.firstOrSuppressed(e, exception);
739:         }
740: 
741:         if (exception != null) {
742:             LOG.warn("Failed to stop checkpoint services.", exception);
743:         }
744:     }
