1308:     @Override
1309:     public void goToCreatingExecutionGraph(@Nullable ExecutionGraph previousExecutionGraph) {
1310:         final CompletableFuture<CreatingExecutionGraph.ExecutionGraphWithVertexParallelism>
1311:                 executionGraphWithAvailableResourcesFuture =
1312:                         createExecutionGraphWithAvailableResourcesAsync(previousExecutionGraph);
1313:         transitionToState(
1314:                 new CreatingExecutionGraph.Factory(
1315:                         this,
1316:                         executionGraphWithAvailableResourcesFuture,
1317:                         LOG,
1318:                         previousExecutionGraph));
