418:     @Nullable
419:     private MemorySegment requestMemorySegment(int targetChannel) {
420:         MemorySegment segment = null;
421:         synchronized (availableMemorySegments) {
422:             checkDestroyed();
423: 
424:             if (!availableMemorySegments.isEmpty()) {
425:                 segment = availableMemorySegments.poll();
426:             } else if (isRequestedSizeReached()) {
427:                 // Only when the buffer request reaches the upper limit(i.e. current pool size),
428:                 // requests an overdraft buffer.
429:                 segment = requestOverdraftMemorySegmentFromGlobal();
430:             }
431: 
432:             if (segment == null) {
433:                 return null;
434:             }
435: 
436:             if (targetChannel != UNKNOWN_CHANNEL) {
437:                 if (++subpartitionBuffersCount[targetChannel] == maxBuffersPerChannel) {
438:                     unavailableSubpartitionsCount++;
439:                 }
440:             }
441: 
442:             checkAndUpdateAvailability();
443:         }
444:         return segment;
445:     }
