172:      * @param minNumberOfMemorySegments minimum number of network buffers
173:      * @param maxNumberOfMemorySegments maximum number of network buffers to allocate
174:      */
175:     LocalBufferPool(
176:             NetworkBufferPool networkBufferPool,
177:             int minNumberOfMemorySegments,
178:             int maxNumberOfMemorySegments) {
179:         this(
180:                 networkBufferPool,
181:                 minNumberOfMemorySegments,
182:                 minNumberOfMemorySegments,
183:                 maxNumberOfMemorySegments,
184:                 0,
185:                 Integer.MAX_VALUE,
186:                 0);
